/// `ContentSamples.NpcBestiarySortingId[netId]` — the entry's display index
/// (`NPCNetIdBestiaryInfoElement.cs:10`). An id outside the table reads 0
/// (the C# dictionary would throw; the port's callers only pass roster ids).
pub fn sorting_id(net_id: i32) -> i32 {
    SORTING_IDS
        .binary_search_by_key(&net_id, |&(id, _)| id)
        .map(|i| SORTING_IDS[i].1)
        .unwrap_or(0)
}

